#[test]
fn layout_matches_c_offsets() {
    assert_eq!(NEXT_ENTRY_OFFSET, 0);
    assert_eq!(PROCESS_NAME_LENGTH, 56);
    assert_eq!(PROCESS_NAME_BUFFER, 64);
    assert_eq!(UNIQUE_PROCESS_ID, 80);
    assert_eq!(SESSION_ID, 100);
    assert_eq!(HEADER_LEN, 104);
    assert_eq!(WTS_PROCESS_INFOW_SIZE, 24);
    assert_eq!(SID_RESERVE_SIZE, 68);
    assert_eq!(WCHAR_SIZE, 2);
}

#[test]
fn enum_rows_match_wine() {
    for row in ENUM_ROWS {
        let checked = match row.call {
            EnumCall::W { reserved, version } => check_enumerate_processes_w(reserved, version)
                .and_then(|()| check_enumerate_processes_ex_w(true, true, 0)),
            EnumCall::Ex {
                level,
                has_info,
                has_count,
            } => check_enumerate_processes_ex_w(has_info, has_count, level),
        };
        assert_eq!(checked, row.expect, "{} result", row.id);
        if row.expect.is_ok() {
            let want: Vec<ProcessEntry> = row
                .entries
                .iter()
                .map(|process| ProcessEntry {
                    session_id: process.session,
                    process_id: process.pid,
                    name: process.name.encode_utf16().collect(),
                })
                .collect();
            let size = process_info_size(&want);
            assert_eq!(
                parse_process_list(row.nt, 0),
                Ok(want),
                "{} entries",
                row.id
            );
            assert_eq!(size, row.size, "{} size", row.id);
        }
    }
}

#[test]
fn query_rows_match_wine() {
    for row in QUERY_ROWS {
        let checked = check_query_session_information(row.has_buffer, row.has_count);
        assert_eq!(checked, row.expect, "{} result", row.id);
        if let Some(route) = row.route {
            assert_eq!(session_info_route_a(row.class), route, "{} route", row.id);
        }
    }
}
